import type { CheckerOutputMode } from '../options.ts';
import {
  canonicalCaseKey,
  isCheckerOutputMode,
  namespaceIdForCase,
  type GoldenCase,
  type GoldenCaseMeta,
} from './goldenCase.ts';

const BEGIN_PREFIX = '// @gtc-golden-begin ';
const END_MARKER = '// @gtc-golden-end';
const CODE_GENERATED =
  '// Code generated by yarn update_fixtures:generator; DO NOT EDIT.';
/** Letter-prefixed hex leaf (see {@link namespaceIdForCase}). */
const NAMESPACE_RE = /^namespace Golden\\(h[a-f0-9]{12}) \{$/u;
const BEGIN_RE = /^\/\/ @gtc-golden-begin (.+)$/u;

function metaToBeginJson(meta: GoldenCaseMeta): string {
  const obj: {
    input: string;
    output: CheckerOutputMode;
    emitPhpstanTypeAliases?: true;
    verbosePhpdoc?: true;
    sealArrayShapes?: true;
  } = {
    input: meta.input,
    output: meta.output,
  };
  if (meta.emitPhpstanTypeAliases === true) {
    obj.emitPhpstanTypeAliases = true;
  }
  if (meta.verbosePhpdoc === true) {
    obj.verbosePhpdoc = true;
  }
  if (meta.sealArrayShapes === true) {
    obj.sealArrayShapes = true;
  }
  return JSON.stringify(obj);
}

function parseMetaJson(raw: string): GoldenCaseMeta {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(`invalid @gtc-golden-begin JSON: ${String(err)}`, {
      cause: err,
    });
  }
  if (typeof parsed !== 'object' || parsed === null) {
    throw new Error('invalid @gtc-golden-begin JSON: expected object');
  }
  if (!('input' in parsed) || typeof parsed.input !== 'string') {
    throw new Error('invalid @gtc-golden-begin JSON: missing input');
  }
  if (!('output' in parsed) || !isCheckerOutputMode(parsed.output)) {
    throw new Error('invalid @gtc-golden-begin JSON: missing/invalid output');
  }
  const meta: {
    input: string;
    output: CheckerOutputMode;
    emitPhpstanTypeAliases?: true;
    verbosePhpdoc?: true;
    sealArrayShapes?: true;
  } = {
    input: parsed.input,
    output: parsed.output,
  };
  if (
    'emitPhpstanTypeAliases' in parsed &&
    parsed.emitPhpstanTypeAliases === true
  ) {
    meta.emitPhpstanTypeAliases = true;
  }
  if ('verbosePhpdoc' in parsed && parsed.verbosePhpdoc === true) {
    meta.verbosePhpdoc = true;
  }
  if ('sealArrayShapes' in parsed && parsed.sealArrayShapes === true) {
    meta.sealArrayShapes = true;
  }
  return meta;
}

function explainLine(stem: string): string {
  return `// Generator success fixtures for ${stem}.IN.`;
}

function formatCaseBlock(meta: GoldenCaseMeta, expected: string): string {
  const id = namespaceIdForCase(meta);
  const body = expected.endsWith('\n') ? expected.slice(0, -1) : expected;
  return `${BEGIN_PREFIX}${metaToBeginJson(meta)}\nnamespace Golden\\${id} {\n${body}\n}\n${END_MARKER}`;
}

/**
 * Encode a suite golden PHP file for `<stem>.IN`.
 * Fails if two distinct cases share the same namespace id.
 */
export function formatGoldenPhp(
  stem: string,
  cases: readonly { readonly meta: GoldenCaseMeta; readonly expected: string }[],
): string {
  const seen = new Map<string, string>();
  const blocks: string[] = [];
  for (const item of cases) {
    const id = namespaceIdForCase(item.meta);
    const key = canonicalCaseKey(item.meta);
    const prev = seen.get(id);
    if (prev !== undefined) {
      if (prev === key) {
        continue;
      }
      throw new Error(`namespace collision Golden\\${id}: ${prev} vs ${key}`);
    }
    seen.set(id, key);
    blocks.push(formatCaseBlock(item.meta, item.expected));
  }

  const header = [
    '<?php',
    '',
    CODE_GENERATED,
    explainLine(stem),
    '',
    'declare(strict_types = 1);',
  ].join('\n');

  if (blocks.length === 0) {
    return `${header}\n`;
  }
  return `${header}\n\n${blocks.join('\n\n')}\n`;
}

function readNamespaceId(
  lines: readonly string[],
  nsIndex: number,
  startLine: number,
  expectedId: string,
): string {
  const nsLine = lines[nsIndex];
  if (nsLine === undefined) {
    throw new Error(`missing namespace after begin at line ${startLine}`);
  }
  const nsMatch = NAMESPACE_RE.exec(nsLine);
  if (nsMatch === null) {
    throw new Error(
      `expected namespace Golden\\h<hex12> { after begin at line ${startLine}`,
    );
  }
  const namespaceId = nsMatch[1];
  if (namespaceId === undefined) {
    throw new Error('never reached');
  }
  if (namespaceId !== expectedId) {
    throw new Error(
      `namespace id mismatch at line ${startLine}: got ${namespaceId}, expected ${expectedId}`,
    );
  }
  return namespaceId;
}

function readCaseBody(
  lines: readonly string[],
  bodyStart: number,
  startLine: number,
): { readonly expected: string; readonly endLine: number; readonly nextIndex: number } {
  let i = bodyStart;
  const bodyLines: string[] = [];
  while (i < lines.length) {
    const cur = lines[i];
    if (cur === undefined) {
      throw new Error('never reached');
    }
    if (cur === '}' && lines[i + 1] === END_MARKER) {
      break;
    }
    bodyLines.push(cur);
    i += 1;
  }
  if (i >= lines.length || lines[i] !== '}') {
    throw new Error(`missing namespace close for case at line ${startLine}`);
  }
  i += 1;
  if (lines[i] !== END_MARKER) {
    throw new Error(`missing ${END_MARKER} for case at line ${startLine}`);
  }
  return {
    expected: bodyLines.length === 0 ? '' : `${bodyLines.join('\n')}\n`,
    endLine: i + 1,
    nextIndex: i + 1,
  };
}

function parseOneCase(
  lines: readonly string[],
  beginIndex: number,
): { readonly item: GoldenCase; readonly nextIndex: number } {
  const beginLine = lines[beginIndex];
  if (beginLine === undefined) {
    throw new Error('never reached');
  }
  const begin = BEGIN_RE.exec(beginLine);
  if (begin === null || begin[1] === undefined) {
    throw new Error('never reached');
  }
  const startLine = beginIndex + 1;
  const meta = parseMetaJson(begin[1]);
  const namespaceId = readNamespaceId(
    lines,
    beginIndex + 1,
    startLine,
    namespaceIdForCase(meta),
  );
  const body = readCaseBody(lines, beginIndex + 2, startLine);
  return {
    item: {
      meta,
      namespaceId,
      expected: body.expected,
      startLine,
      endLine: body.endLine,
    },
    nextIndex: body.nextIndex,
  };
}

/**
 * Parse a suite `*.golden.php` source into cases with 1-based line ranges.
 */
export function parseGoldenPhp(source: string): GoldenCase[] {
  const lines = source.split('\n');
  const cases: GoldenCase[] = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line === undefined) {
      throw new Error('never reached');
    }
    if (!line.startsWith(BEGIN_PREFIX)) {
      i += 1;
      continue;
    }
    const { item, nextIndex } = parseOneCase(lines, i);
    cases.push(item);
    i = nextIndex;
  }
  return cases;
}
